    "id": "q_1_15",
    "chapter": "chapter_1",
    "level": "L2",
    "type": "考核题",
    "topic": "绝对值距离",
    "question": "已知一队数最后奔向极限 $L = 5$。妹妹提出误差 $\\varepsilon = 0.1$，如果姐姐选了关口 $N=50$，这意味着当 $n > 50$ 时，$a_n$ 的值一定在哪个范围内？",
    "options": [
      {
        "value": "A",
        "text": "大于 5.1"
      },
      {
        "value": "B",
        "text": "介于 4.9 和 5.1 之间"
      },
      {
        "value": "C",
        "text": "小于 4.9"
      },
      {
        "value": "D",
        "text": "介于 0 和 5 之间"
      }
    ],
    "correct": "B",
    "explanations": {
      "B": "$|a_n - 5| < 0.1$，意味着 $a_n$ 离 5 的距离不到 0.1，即 $5 - 0.1 < a_n < 5 + 0.1$，所以落在 4.9 到 5.1 之间。",
      "A": "只看了大于的部分而且方向弄反了。",
      "C": "只看了小于的部分。",
      "D": "毫无根据的范围猜测。"
    }
