    "question": "仔细观察下面的机器，哪一台**不是**多项式？",
    "options": [
      {
        "value": "A",
        "text": "$f(a) = a \\times a$"
      },
      {
        "value": "B",
        "text": "$f(a) = 5$"
      },
      {
        "value": "C",
        "text": "$f(a) = a + 3$"
      },
      {
        "value": "D",
        "text": "$f(a) = \\frac{1}{a}$"
      }
    ],
    "correct": "D",
    "explanations": {
      "D": "多项式的建造规则中，不能把变量 $a$ 放在除数的位置上（不能除以 $a$）。A 是乘法，B 是什么手都没动直接用数字原料，C 是加法，它们都是多项式。",
      "B": "常数函数看起来不像多项式，但它符合定义（不需动手，直接吐出原料）。"
    }
