      "A": "这就是中值定理的核心公式：两点的落差（$f(b)-f(a)$）等于某个瞬间的速度（$f'(c)$）乘以经历的时间或距离（$b-a$）。这也是“平均变化率 $=$ 某一点的瞬时导数”的变形。",
      "B": "这说明处处匀速，是个特例。",
      "C": "罗尔定理的一个条件。",
      "D": "胡拼乱凑的字母。"
